begin;

alter table public.media_gallery_items add column if not exists media_type text not null default 'image';
alter table public.media_gallery_items add column if not exists video_url text;
alter table public.media_gallery_items alter column image_asset_id drop not null;
alter table public.media_gallery_items drop constraint if exists media_gallery_category_check;
alter table public.media_gallery_items drop constraint if exists media_gallery_items_category_check;
update public.media_gallery_items set category='Events' where category in ('Event','Awards','Award');
update public.media_gallery_items set category='Office Culture' where category in ('Office','Culture','Team');
update public.media_gallery_items set status='unpublished' where category not in ('Videos','Events','Office Culture') and status='published';
alter table public.media_gallery_items alter column category set default 'Events';
alter table public.media_gallery_items drop constraint if exists media_gallery_items_public_category_check;
alter table public.media_gallery_items add constraint media_gallery_items_public_category_check check(status<>'published' or category in ('Videos','Events','Office Culture'));


commit;

select category,media_type,status,count(*) as item_count from public.media_gallery_items group by category,media_type,status order by category,media_type,status;